; once.asm -- chapter 27: 5S read once a frame, by the routine
; generated by gen27.py
        INCLUDE "msx.inc"
        OUTPUT "once.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; poll.asm's six figures, with the status read as status.asm reads it: once a
; frame, by the interrupt routine. For 48 frames the six are on lines 88 to
; 103, then for 48 the same six in two rows, three on a line; every frame
; the table is turned by 2 entries more only if the routine found 5S.
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
copy    EQU $C400               ; six on a line, twice ($D0 sent once)
copy2   EQU $C480               ; three on a line, twice
status  EQU VARS                ; what the routine read
base    EQU VARS + 1            ; the copy in use
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 160
        otir
        ld hl, atts             ; the two copies: each six entries twice
        ld de, copy
        ld bc, 24
        ldir
        ld hl, atts
        ld bc, 24
        ldir
        ld hl, rows
        ld de, copy2
        ld bc, 24
        ldir
        ld hl, rows
        ld bc, 24
        ldir
        VRAM_WRITE $1B00        ; the attributes
        ld hl, atts
        ld c, VDP_DATA
        ld b, 25
        otir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP irq
        ld (IM2_JUMP), a
        ld hl, irq
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E2          ; the display on, sprites of 16 x 16, the interrupt on
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        call frame              ; to the end of this paper: the next wait is whole
        ei
        ld d, 0                 ; k, times 4: the first entry sent
        ld hl, copy             ; six on a line
        ld (base), hl
        ld e, 48
        call frames
        ld hl, copy2            ; three on a line
        ld (base), hl
        ld e, 48
        call frames
        di
done:   jr done

; frames: E frames, each the table from base + 4k, k going up by 2,
; round 6, after a frame whose status had 5S
frames: halt                    ; the paper ended: the routine read the status
        ld a, (status)          ; 14
        and $40                 ;  8  5S?
        jr z, m0                ; 13, or 8
        ld a, d                 ;  5  a sprite left out: k + 2, round 6
        add a, 8                ;  8
        cp 24                   ;  8
        jr c, inside            ; 13, or 8
        sub 24                  ;  8
inside: ld d, a                 ;  5
m0:     VRAM_WRITE $1B00        ; 40
        ld hl, (base)           ; 17  the copy from entry k
        ld b, 0                 ;  8
        ld c, d                 ;  5
        add hl, bc              ; 12
        ld c, VDP_DATA          ;  8
        ld b, 24                ;  8  six entries
        otir                    ; 23 a byte, 18 the last
m1:     dec e
        jr nz, frames
        ret

; irq: the status, read once at the end of the paper
irq:    push af
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C and the number
        ld (status), a          ; 14
        pop af
        ei
        ret

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
atts:
        db $57, $10, $00, $01
        db $57, $38, $00, $01
        db $57, $60, $00, $01
        db $57, $88, $00, $01
        db $57, $B0, $00, $01
        db $57, $D8, $00, $01
        db $D0
rows:
        db $4F, $10, $00, $01
        db $5F, $38, $00, $01
        db $4F, $60, $00, $01
        db $5F, $88, $00, $01
        db $4F, $B0, $00, $01
        db $5F, $D8, $00, $01
        db $D0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
